  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nmodel User {\n  id         String              @id @default(uuid())\n  email      String              @unique\n  password   String\n  firstName  String\n  lastName   String\n  roleId     String\n  role       Role                @relation(fields: [roleId], references: [id])\n  movements  InventoryMovement[]\n  activities ActivityLog[]\n  createdAt  DateTime            @default(now())\n  updatedAt  DateTime            @updatedAt\n}\n\nmodel Role {\n  id          String   @id @default(uuid())\n  name        String   @unique // Admin, Manager, Warehouse Staff, Sales Staff, Accountant\n  description String?\n  users       User[]\n  createdAt   DateTime @default(now())\n}\n\nmodel Product {\n  id                String              @id @default(uuid())\n  name              String\n  sku               String              @unique\n  description       String?\n  category          String // e.g. T-Shirts, Hoodies, Jeans, Jackets, Shirts\n  size              String // e.g. S, M, L, XL, XXL\n  color             String // e.g. Red, Blue, Black, White\n  price             Float // Selling price\n  cost              Float // Cost price\n  quantityInStock   Int                 @default(0)\n  lowStockThreshold Int                 @default(15)\n  supplierId        String\n  supplier          Supplier            @relation(fields: [supplierId], references: [id])\n  orderItems        OrderItem[]\n  poItems           PurchaseOrderItem[]\n  movements         InventoryMovement[]\n  createdAt         DateTime            @default(now())\n  updatedAt         DateTime            @updatedAt\n}\n\nmodel Supplier {\n  id             String          @id @default(uuid())\n  name           String\n  contactName    String?\n  email          String?\n  phone          String?\n  address        String?\n  products       Product[]\n  purchaseOrders PurchaseOrder[]\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n}\n\nmodel Customer {\n  id          String   @id @default(uuid())\n  name        String\n  contactName String?\n  email       String?\n  phone       String?\n  address     String?\n  category    String // B2B Boutique, Wholesale Retailer, Department Store, E-commerce\n  debt        Float    @default(0.0)\n  creditLimit Float    @default(10000.0)\n  leads       Lead[]\n  orders      Order[]\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\nmodel Lead {\n  id         String   @id @default(uuid())\n  customerId String\n  customer   Customer @relation(fields: [customerId], references: [id])\n  status     String // NEW, CONTACTED, PROPOSAL, NEGOTIATION, WON, LOST\n  value      Float\n  source     String // Referral, Trade Show, Website, Cold Call\n  notes      String?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n}\n\nmodel Order {\n  id          String      @id @default(uuid())\n  orderNumber String      @unique\n  customerId  String\n  customer    Customer    @relation(fields: [customerId], references: [id])\n  status      String // PENDING, COMPLETED, CANCELLED\n  subtotal    Float       @default(0.0)\n  discount    Float       @default(0.0)\n  tax         Float       @default(0.0)\n  totalAmount Float\n  orderDate   DateTime    @default(now())\n  items       OrderItem[]\n  invoices    Invoice[]\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n}\n\nmodel OrderItem {\n  id        String   @id @default(uuid())\n  orderId   String\n  order     Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product  @relation(fields: [productId], references: [id])\n  quantity  Int\n  price     Float\n  createdAt DateTime @default(now())\n}\n\nmodel PurchaseOrder {\n  id          String              @id @default(uuid())\n  poNumber    String              @unique\n  supplierId  String\n  supplier    Supplier            @relation(fields: [supplierId], references: [id])\n  status      String // PENDING, RECEIVED, CANCELLED\n  totalAmount Float\n  poDate      DateTime            @default(now())\n  items       PurchaseOrderItem[]\n  createdAt   DateTime            @default(now())\n  updatedAt   DateTime            @updatedAt\n}\n\nmodel PurchaseOrderItem {\n  id              String        @id @default(uuid())\n  purchaseOrderId String\n  purchaseOrder   PurchaseOrder @relation(fields: [purchaseOrderId], references: [id], onDelete: Cascade)\n  productId       String\n  product         Product       @relation(fields: [productId], references: [id])\n  quantity        Int\n  cost            Float\n  createdAt       DateTime      @default(now())\n}\n\nmodel InventoryMovement {\n  id          String   @id @default(uuid())\n  productId   String\n  product     Product  @relation(fields: [productId], references: [id])\n  quantity    Int\n  type        String // INCOMING, OUTGOING, TRANSFER, ADJUSTMENT\n  fromZone    String?\n  toZone      String?\n  referenceId String? // ID of sales order or purchase order, or manual ID\n  userId      String?\n  user        User?    @relation(fields: [userId], references: [id])\n  createdAt   DateTime @default(now())\n}\n\nmodel WarehouseZone {\n  id           String   @id @default(uuid())\n  name         String\n  code         String   @unique // e.g. ZONE-A, ZONE-B\n  capacity     Int\n  currentUsage Int      @default(0)\n  description  String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n\nmodel Invoice {\n  id            String    @id @default(uuid())\n  invoiceNumber String    @unique\n  orderId       String\n  order         Order     @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  amount        Float\n  status        String // UNPAID, PARTIAL, PAID, OVERDUE\n  dueDate       DateTime\n  issuedDate    DateTime  @default(now())\n  payments      Payment[]\n  createdAt     DateTime  @default(now())\n}\n\nmodel Payment {\n  id            String   @id @default(uuid())\n  paymentNumber String   @unique\n  invoiceId     String\n  invoice       Invoice  @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  amount        Float\n  paymentMethod String // Bank Transfer, Credit Card, Cash, Check\n  paymentDate   DateTime @default(now())\n  reference     String?\n  createdAt     DateTime @default(now())\n}\n\nmodel Expense {\n  id          String   @id @default(uuid())\n  title       String\n  category    String // Rent, Utilities, Logistics, Marketing, Salaries, Office\n  amount      Float\n  description String?\n  date        DateTime @default(now())\n  createdAt   DateTime @default(now())\n}\n\nmodel CloudResource {\n  id        String   @id @default(uuid())\n  name      String // VPC, Subnet Public, Subnet Private, VPN, Load Balancer, NAT Gateway, Internet Gateway, Firewall, CDN\n  type      String // network, compute, storage, security\n  status    String // ACTIVE, DEGRADED, INACTIVE\n  ipAddress String?\n  zone      String?\n  createdAt DateTime @default(now())\n}\n\nmodel CloudMetric {\n  id                String   @id @default(uuid())\n  timestamp         DateTime @default(now())\n  cpuUsage          Float // percentage\n  memoryUsage       Float // percentage\n  diskUsage         Float // percentage\n  apiResponseTime   Float // ms\n  apiUptime         Float // percentage\n  requestsCount     Int\n  errorsCount       Int\n  activeConnections Int\n}\n\nmodel ActivityLog {\n  id        String   @id @default(uuid())\n  userId    String?\n  user      User?    @relation(fields: [userId], references: [id])\n  action    String // e.g. Login, Create Order, Stock Update\n  details   String?\n  timestamp DateTime @default(now())\n}\n",
